head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup");
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "500px",
        height: "500px"
    };
    $p.openPopup("selectbox_gridviewitemset_WEFF-917_(WSQ-4410)_popup.xml", options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
